function tgConfirm(t,x,fn){$('<div/>').appendTo('body').kendoDialog({width:420,title:t,closable:true,modal:true,content:'<p style="margin:0;color:#3d4465;">'+x+'</p>',actions:[{text:'Cancelar'},{text:'Confirmar',primary:true,action:function(){fn();}}],close:function(){this.destroy();}}).data('kendoDialog').open();}
function tgAlert(t,x){$('<div/>').appendTo('body').kendoDialog({width:380,title:t,closable:true,modal:true,content:'<p style="margin:0;color:#3d4465;">'+x+'</p>',actions:[{text:'OK',primary:true}],close:function(){this.destroy();}}).data('kendoDialog').open();}
function onWndGestionCerrar(){$('#wndGestionBody').empty();}
function abrirModal(url,params){$.get(url,params||{},function(html){$('#wndGestionBody').html(html);$('#wndGestion').data('kendoWindow').center().open();});}
function cargarMaquinas(){location.reload();}
function cargarEnsambles(){location.reload();}
function cargarProgramas(){location.reload();}
function cargarAcomodos(){location.reload();}
$(document).on('click','#btnAgregarMaquina',function(){abrirModal(TG.urls.agregarMaquinaModal);});
$(document).on('click','.btn-edit-maquina',function(){abrirModal(TG.urls.editarMaquinaModal,{maquinaId:$(this).data('id')});});
$(document).on('click','.btn-del-maquina',function(){var id=$(this).data('id');tgConfirm('Eliminar maquina','Esta accion no se puede deshacer.',function(){$.post(TG.urls.eliminarMaquina,{maquinaId:id},function(r){if(r.success)location.reload();else tgAlert('Error',r.message);});});});
$(document).on('click','#btnAgregarEnsamble',function(){abrirModal(TG.urls.agregarEnsambleModal);});
$(document).on('click','.btn-edit-ensamble',function(){abrirModal(TG.urls.editarEnsambleModal,{ensambleId:$(this).data('id')});});
$(document).on('click','.btn-del-ensamble',function(){var id=$(this).data('id');tgConfirm('Eliminar ensamble','Esta accion no se puede deshacer.',function(){$.post(TG.urls.eliminarEnsamble,{ensambleId:id},function(r){if(r.success)location.reload();else tgAlert('Error',r.message);});});});
$(document).on('click','#btnAgregarPrograma',function(){abrirModal(TG.urls.agregarProgramaModal);});
$(document).on('click','.btn-edit-programa',function(){abrirModal(TG.urls.editarProgramaModal,{programaId:$(this).data('id')});});
$(document).on('click','.btn-del-programa',function(){var id=$(this).data('id');tgConfirm('Eliminar programa','Esta accion no se puede deshacer.',function(){$.post(TG.urls.eliminarPrograma,{programaId:id},function(r){if(r.success)location.reload();else tgAlert('Error',r.message);});});});
$(document).on('click','#btnAgregarAcomodo',function(){abrirModal(TG.urls.agregarAcomodoModal);});
$(document).on('click','.btn-edit-acomodo',function(){abrirModal(TG.urls.editarAcomodoModal,{ensambleId:$(this).data('id')});});
$(document).on('click','.acomodo-toggle',function(){var t=$(this).data('target');$('#'+t).toggle();$(this).find('.acomodo-arrow').toggleClass('fa-chevron-right fa-chevron-down');});
